//! g2p parity battery: the expectations in `testdata/g2p_battery.tsv` are
//! generated by the Python reference (`scripts/gen_phoneme_data.py` writes
//! them from `jyutping` / `ko_pron`), so any drift in the ported tables or
//! algorithms shows up here.
//!
//! For Cantonese the battery records the full candidate set per character
//! (Python's single-reading pick is hash-order dependent); the port must
//! choose one of the candidates. Korean rows compare exactly.

use libresvip_core::core::lyric_phoneme::{cantonese, korean};

#[test]
fn matches_python_reference() {
    let battery = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .join("testdata")
        .join("g2p_battery.tsv");
    let text = std::fs::read_to_string(&battery)
        .unwrap_or_else(|error| panic!("read {}: {error}", battery.display()));
    let mut checked = 0usize;
    for line in text.lines() {
        let mut fields = line.splitn(3, '\t');
        let (Some(kind), Some(input), Some(expected)) =
            (fields.next(), fields.next(), fields.next())
        else {
            continue;
        };
        match kind {
            "jyutping" => {
                let candidates: Vec<Option<Vec<String>>> =
                    serde_json::from_str(expected).expect("battery row json");
                let actual = cantonese::get_jyutping(input).expect("dictionary");
                assert_eq!(
                    actual.len(),
                    candidates.len(),
                    "{input}: per-character count differs"
                );
                for (index, (actual, candidates)) in
                    actual.iter().zip(candidates.iter()).enumerate()
                {
                    match (actual, candidates) {
                        (Some(actual), Some(candidates)) => assert!(
                            candidates.contains(actual),
                            "{input}[{index}]: picked {actual}, Python candidates {candidates:?}"
                        ),
                        (None, None) => {}
                        (actual, candidates) => panic!(
                            "{input}[{index}]: presence mismatch: {actual:?} vs {candidates:?}"
                        ),
                    }
                }
            }
            scheme => {
                let name = scheme.strip_prefix("korean:").expect("kind");
                let actual = korean::romanise(input, name).expect("romanise");
                assert_eq!(
                    actual, expected,
                    "{name}({input}): python said {expected:?}"
                );
            }
        }
        checked += 1;
    }
    assert!(checked >= 40, "battery rows missing: {checked}");
}
